R=[
dict(no=21,q=r"상수 $a$ $(a\ne3\sqrt5)$와 최고차항의 계수가 음수인 이차함수 $f(x)$에 대하여 함수 $g(x)=\begin{cases}x^3+ax^2+15x+7 & (x\le0)\\ f(x) & (x>0)\end{cases}$이 다음 조건을 만족시킨다. $g(-2)+g(2)$의 값은?",
 cond=r"(가) 함수 $g(x)$는 실수 전체의 집합에서 미분가능하다.\\(나) $x$에 대한 방정식 $g'(x)\times g'(x-4)=0$의 서로 다른 실근의 개수는 $4$이다.",
 ch=["30","32","34","36","38"],ans="2",fig=None,th="09",lk=["07"],
 fj=r"(가)로 $f(x)=px^2+15x+7$ ($p<0$)이 정해지고, (나)에서 $g'$의 근 $\alpha,\beta,\gamma$와 그것을 $4$ 평행이동한 근이 겹쳐 총 4개가 되어야 한다.",
 bh="문제해결",rs=["조건의 식 번역","대칭성·주기성 활용","미지수 소거·연립"],st=["S16","S18"],
 sol=r"$f(x)=px^2+15x+7$, $f'$의 근 $-\frac{15}{2p}>0$. $x<0$에서 $g'=0$의 두 근 $\alpha<\beta<0$과 $\beta=\alpha+4$, $-\frac{15}{2p}=\beta+4$. $3x^2+2ax+15=0$: $2\alpha+4=-\frac{2a}3$, $\alpha(\alpha+4)=5$ → $\alpha=-5$, $a=9$, $\beta=-1$, $p=-\frac52$. $g(-2)=5$, $g(2)=27$, 합 $32$"),
dict(no=22,q=r"최고차항의 계수가 $1$인 삼차함수 $f(x)$가 다음 조건을 만족시킨다. $f'\left(-\dfrac14\right)=-\dfrac14$, $f'\left(\dfrac14\right)<0$일 때, $f(8)$의 값을 구하시오.",
 cond=r"함수 $f(x)$에 대하여 $f(k-1)f(k+1)<0$을 만족시키는 정수 $k$는 존재하지 않는다.",
 ch=None,ans="483",fig=None,th="13",lk=["09","10"],
 fj=r"조건은 '간격 2인 정수쌍에서 부호가 바뀌지 않는다'이므로, $f(x)=0$의 실근 개수(1, 2, 3)로 나눠 근이 연속한 정수 사이에 몰려 있어야 함을 본다.",
 bh="문제해결",rs=["경우 나누기","정수 조건으로 후보 좁히기","그래프·도형 해석"],st=["S09","S19"],
 sol=r"모든 정수 $k$에 대해 $f(k-1)f(k+1)\ge0$. (i) 실근 1개: 불가. (ii) 실근 2개: $f=x(x-1)^2$ 또는 $x^2(x-1)$ — $f'\left(-\frac14\right)=-\frac14$ 불만족. (iii) 실근 3개: $b=m+1$, $c=m+2$, $m=-1$ → $f=(x-a)(x^2-x)$, $f'\left(-\frac14\right)=\frac{11}{16}+\frac32a=-\frac14$ → $a=-\frac58$. $f(8)=\frac{69}8\cdot56=483$"),
dict(no=23,q=r"두 양수 $p,q$와 함수 $f(x)=x^3-3x^2-9x-12$에 대하여 실수 전체의 집합에서 연속인 함수 $g(x)$가 다음 조건을 만족시킬 때, $p+q$의 값은?",
 cond=r"(가) 모든 실수 $x$에 대하여 $xg(x)=|xf(x-p)+qx|$이다.\\(나) 함수 $g(x)$가 $x=a$에서 미분가능하지 않은 실수 $a$의 개수는 $1$이다.",
 ch=["6","7","8","9","10"],ans="3",fig=None,th="07",lk=["09"],
 fj=r"$g(x)=\pm|f(x-p)+q|$ ($x\gtrless0$)이므로 연속 조건으로 $f(-p)+q=0$이고, 꺾이는 점이 1개가 되도록 극값 위치를 맞춘다.",
 bh="추론",rs=["그래프·도형 해석","조건의 식 번역"],st=["S16"],
 sol=r"$f$: 극댓값 $f(-1)=-7$, 극솟값 $f(3)=-39$. 연속 → $f(-p)+q=0$. $|f(x-p)+q|$의 그래프는 평행이동 후 $x$축 아래를 뒤집은 것; 미분불가능점 1개 → 원점이 극대점($p=1$, $q=7$). $p+q=8$"),
]
